use vstd::prelude::*;

verus! {

fn concat(a: &[i32], b: &[i32]) -> (res: Vec<i32>)
    ensures
        res.len() == a.len() + b.len(),
        forall|i: int| 0 <= i && i < a.len() ==> res[i as usize] == a[i as usize],
        forall|j: int| 0 <= j && j < b.len() ==> res[(a.len() + j) as usize] == b[j as usize],
{
    let mut res = Vec::<i32>::with_capacity(a.len() + b.len());
    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            res.len() == i,
            forall|k: int| 0 <= k && k < i as int ==> res[k as usize] == a[k as usize],
        decreases a.len() - i,
    {
        res.push(a[i]);
        i += 1;
    }
    let mut j: usize = 0;
    while j < b.len()
        invariant
            j <= b.len(),
            res.len() == a.len() + j,
            forall|k: int| 0 <= k && k < a.len() ==> res[k as usize] == a[k as usize],
            forall|l: int| 0 <= l && l < j as int ==> res[(a.len() + l) as usize] == b[l as usize],
        decreases b.len() - j,
    {
        res.push(b[j]);
        j += 1;
    }
    res
}

}
